fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // The problem guarantees:
    // 1. arr1.len() == arr2.len()
    // 2. No element of arr2 is zero
    // 3. Each quotient fits in a 32-bit signed integer range
    //
    // We simply perform element-wise integer division (floor division for unsigned ints).
    assert_eq!(
        arr1.len(),
        arr2.len(),
        "Input arrays must have the same length"
    );

    let mut result = Vec::with_capacity(arr1.len());
    for (a, b) in arr1.iter().zip(arr2.iter()) {
        // b is guaranteed non-zero
        result.push(a / b);
    }
    result
}

